return ['domain'=>'lingua-forge','plural-forms'=>'nplurals=2; plural=n != 1;','language'=>'fa_IR','project-id-version'=>'Lingua Forge 2.1.0','pot-creation-date'=>'2026-07-29T14:57:34+00:00','po-revision-date'=>'2026-07-05 22:45+0000','x-generator'=>'Loco https://localise.biz/','messages'=>['Lingua Forge'=>'لانگوا فورج','https://github.com/leotiger/lingua-forge'=>'https://github.com/leotiger/lingua-forge','Multilingual routing, complete multilingual SEO (hreflang, Open Graph, Schema.org, sitemap), and AI content tools for WordPress. Language detection, URL routing, translation, content generation, and a full SEO layer — no companion plugin required.'=>'مسیر چندزبانه، سئو کامل چندزبانه (hreflang، Open Graph، Schema.org، نقشه سایت)، و ابزارهای محتوای هوش مصنوعی برای وردپرس. تشخیص زبان، مسیر URL، ترجمه، تولید محتوا، و یک لایه کامل سئو — بدون نیاز به افزونه همراه.','Uli Hake'=>'اولی هاکه','https://lingua-forge.com'=>'https://lingua-forge.com','Translate'=>'ترجمه','Lingua Forge — Quick Translate'=>'لانگوا فورج — ترجمه سریع','Informative'=>'اطلاعاتی','Persuasive'=>'قانع‌کننده','Storytelling'=>'داستان‌گویی','Technical'=>'فنی','Conversational'=>'گفتگو محور','Translate missing'=>'ترجمه‌های مفقود','%d comment translation created.'=>'%d ترجمهٔ نظر ایجاد شد.' . "\0" . '%d ترجمهٔ نظر ایجاد شد.','%d pair could not be translated yet (e.g. a nested reply waiting on its parent, or a language currently in cooldown after repeated failures).'=>'%d جفت هنوز ترجمه نشده است (مثلاً یک پاسخ تو در تو که منتظر والد خود است، یا زبانی که پس از شکست‌های مکرر در حالت خنک‌سازی است).' . "\0" . '%d جفت هنوز ترجمه نشده است (مثلاً پاسخ‌های تو در تو که منتظر والد خود هستند، یا زبانی که پس از شکست‌های مکرر در حالت خنک‌سازی است).','Permission denied.'=>'دسترسی ممنوع است.','Cannot determine target language from slug.'=>'نمی‌توان زبان هدف را از slug تشخیص داد.','Invalid post type.'=>'نوع پست نامعتبر.','Invalid or primary language.'=>'زبان نامعتبر یا اصلی.','Template not found or not stored in the database.'